src=json.loads(SOURCE.read_text());a938=next(a for a in src if a['number']==938);b938={b['id']:b['text'] for b in a938['blocks']}
e={
'A0937-B0003':'名称：伊卡索斯（Iocanthos，亦拼作 Iocanthus）',
'A0937-B0009':'次星区：戈尔根纳疆域',
'A0937-B0011':'人口：50 亿',
'A0937-B0021':'伊卡索斯又拼作 Iocanthus。这是一个无法无天的世界，军阀率领庞大军队，在丛林、森林与平原间不断交战。',
'A0937-B0026':'每隔五年，内政部官员组成的征收队便来到伊卡索斯，收取鬼火花什一税。军阀交出采集的鬼火花粉，换取武器、载具、燃料、净水与其他必需品。上缴花粉最多的军阀，会被承认为行星总督，获得帝国援助的大部分份额，并取得“维尔瓦”头衔，意为“诸侯之首”或“国王”。',
'A0937-B0028':'这一头衔声望极高，确认了持有者是伊卡索斯最危险、最精明强悍的军阀。本文所述时任总督是维尔瓦“王者”颅骨：他本身便是可怕的战士，麾下聚集着庞大的疯子与杀手军队，据说所向无敌。军阀除上缴鬼火花，还必须交出灵能者。但收走灵能者的不是内政部，而是一群身着灰制服、不报姓名的人。他们将灵能者赶上线条流畅的黑船，随即离去。',
'A0937-B0030':'内政部完全接受伊卡索斯的现状。众军阀争相寻找最后一朵鬼火花，反而使花粉采集极有效率。若改由内政部直接接管，帝国卫队首先得付出巨大代价征服星球；接管后，官僚机构也很难达到军阀搜遍每一朵花的狂热程度。因此，内政部索性让军阀承担苦工，并确信他们不敢反叛：只要切断枪械与燃料供应，便足以制约他们。',
'A0937-B0033':'伊卡索斯的军阀通常自称“瓦”，意为部落君主。他们不断争夺鬼火花收获权。鬼火花无法正常栽培，采完一片就必须另寻新的生长地，军队因此始终在迁移。他们成群穿越主大陆，一旦相遇便激烈交战。广阔平原、幽暗密林与险峻山口之间，旧战场星罗棋布，到处可见烧毁的载具和被岁月漂白的尸骨。',
'A0937-B0036':'星球拥有四块主要大陆和广阔岛链。只有最大的一块大陆有人居住；其地形多山、多岩石，南部则覆盖茂密森林。',
'A0937-B0038':'最大的永久聚居地是痛苦港，一座设防城镇，人口为 2,567,560 人。这里设有太空港，也是内政部在全星球唯一办事机构的所在地。',
'A0937-B0040':'痛苦港以北不远的山中，有一个名为斯特恩希望的村落。它随星球上唯一一座大教堂的兴建而发展起来。教堂于 813.M41 动工，约在 815.M41 祝圣。',
'A0937-B0042':'除此之外，唯一值得一提的文明据点是黎明修道院，也是修女会在卡利西斯星区的主要训练设施。初学者在这里接受训练，成为正式修女。',
'A0937-B0052':'当地货币称“灵魂币”。许多人相信，钱币永远沾染着雇佣兵的鲜血，因此把买卖也看作对阵亡战士灵魂的交易。',
'A0937-B0054':'主要出口——伊卡索斯唯一重要的出口品是鬼火花粉，它对维持朦胧星域的帝国刑罚军团至关重要。',
'A0937-B0059':'许多稳定的亚空间航路从伊卡索斯出发，通往德里亚、辛提拉、卢格努姆、瑟菲瑞斯次星、41 普莱、齐尔曼领域与希德等世界。',
'A0938-B0009':'次星区：戈尔根纳疆域',
'A0938-B0011':'人口：120 亿',
'A0938-B0017':'什一税等级：第一级极等',
'A0938-B0024':'瑟菲瑞斯次星矿藏极富，矿区大如城市，数十亿农奴在其中劳作；它也是卡利西斯星区贫富分化最为悬殊的世界。冰雪与昏暮笼罩大地，野蛮变种人潜伏四处，人们在地下深处的繁重苦役中度过一生。帝国对矿产的贪婪开采，使它同时成为星区最富有、也最贫困的世界。',
'A0938-B0026':'瑟菲瑞斯次星寒冷多风暴，厚云遮蔽地表。除极地小片海域外，这里没有海洋；大气中的水汽主要来自地壳深处，从废损矿井和天然间歇泉喷出，像脓疱般遍布星球。地表一半是伤口般切入岩层的巨型露天矿，一半是积雪深厚的密林。林间散布着昔日企图统治此地、如今已覆灭的王国遗迹。暴风雪无休无止，人们普遍愚昧，事事沿用陈旧方法；若非地下矿藏丰厚，这里只会是一处无足轻重的偏远荒地。',
'A0938-B0029':'整个人类帝国本就是封建帝国，但瑟菲瑞斯次星将这种制度推至极端。每个生于此地的人都必须有主人，并将全部产出的十分之九交给对方；对大多数人来说，产出就是从矿壁上凿下的矿石。绝对君主拉克莉玛三世女王位于制度顶端。数十亿农奴的劳役支配权，属于她任命的男爵，或向王室购买这些权利的贵族家族与商业财团。女王也有自己的主人——帝国。她必须上缴数量惊人的矿石、金属与未加工燃料，履行星球的什一税义务。这里的税额是卡利西斯星区之最，若失去如此庞大的原料产出，全星区经济都会受到严重冲击。',
'A0938-B0033':'维系这种封建秩序的主要有两股力量。第一是传统的重压：矿井里的每个农奴，都重复着父祖的劳动，往往连面对的矿壁也没有变。第二便是武力。王室垄断武器与其他技术，是当地社会在许多方面如此落后的原因之一。女王的皇家天灾装备激光枪、手榴弹与链锯刃，却穿着华丽如彩色玻璃的甲胄，形成强烈反差。他们人数虽少，技术优势却足以镇压矿区的一次次起义。行星历史中，满是数千农奴倒在激光齐射之下的惨案。',
'A0938-B0050':'经济：矿片与矿块——矿山和村落的生活完全围绕无休止的采矿展开，以至于矿石碎片和矿块有时就充当通用货币。',
'A0938-B0052':'主要出口：瑟菲瑞斯次星是卡利西斯星区最大的出口世界。若没有它大量供应的矿石、金属与燃料，星区贸易便无法正常运转。',
'A0938-B0054':'镜盾：皇家天灾使用的大型长方形盾牌，能遮住人体约三分之二的面积。它由多层彩色玻璃构成，这种材料也广泛用于当地男爵的建筑与装备。层叠结构产生镜面反射效果，足以抵挡部分低功率激光射击。',
'A0938-B0060':'公地区——农奴与其主人男爵的居住区。农奴小屋紧挤着狭窄街道，一家数代人常共住一间房，只靠蜡烛照明。男爵也住在此区，但拥有舒适宅邸和城堡，以及众多卫兵、仆人。他们出行时，名为恶臭守望者的专门卫队会驱赶靠得过近的农奴，并挥动香炉，用香气遮去农奴身上的臭味。',
'A0938-B0062':'采掘区——所有开采矿石及其他材料的区域。农奴在矿道中劳作，每人都有划定的采掘位置，并用自己的血在附近岩壁留下标记。拆解行会工程师炸开新的工作面时，农奴蜂拥争抢位置，常有人被踩踏致死。',
'A0938-B0064':'破碎区——戈尔戈尼德最深处，危险得连农奴也不在那里正常劳作。因犯罪遭追捕的农奴藏身于此；水污染与辐射不断催生的变种人，也聚集在这里。变种人在当地具有特殊地位，最强者甚至生活优裕，通常是可怕的怪物或拥有异能的灵能者。据说，戈尔戈尼德经济有很大一部分依靠这里的矿石黑市：变种人采矿后，将其秘密卖给参与非法交易的农奴。',
'A0938-B0068':'憎恶者——彻底丧失希望的人，以受雇刺杀为生。他们杀死阻挡自己的人，把充满自身灵魂的绝望也带给他人。',
'A0938-B0070':'孤儿远征——搜寻并秘密绑架身具异能者的组织，没人知道俘虏随后会遭遇什么。',
'A0938-B0072':'花岗岩王冠——或许是所有教派中最可怕的一支，以一只失明之眼为标志。据说其领袖权势极大，连变种人也向他们纳贡。关于这个教派的故事在农奴间口耳相传，越传越骇人。',
'A0938-B0076':'至少一份资料将星球拼作 Sephiris Secundus。这大概是笔误，因为同一份资料的其余部分都一致使用 Sepheris Secundus。',
}
# These malformed source blocks contain intact English embedded between Chinese; retain it verbatim.
t=b938['A0938-B0058'];en=t[t.index('Gorgonid Prime —'):t.index('戈尔戈尼德一号是')];tail='Gorgonid Prime divided into several areas: '
e['A0938-B0058']='帝国卫队征兵：庞大人口使瑟菲瑞斯次星成为潜在兵源，但居民健康普遍恶劣，真正适合服役的比例很小。此外，征兵还可能让受压迫者意识到，矿井之外存在另一种生活；统治者同样忌惮这一点。\n\n'+en+'\n\n戈尔戈尼德主矿区——行星上规模最大的采矿设施群之一。矿石由起重机与升降机运至上层，再送往太空港，出售给其他世界。大批农奴日复一日清晨下矿、晚间回到破败家中，几乎一生都不曾离开。男爵严密监督开采，拿走产量的十分之九；农奴生活事事受其喜怒摆布，连结婚也须由男爵准许。\n\n'+tail+'\n戈尔戈尼德主矿区分为以下区域：'
t=b938['A0938-B0066'];head='Cults of the Gorgonid';ens='The Gorgonid inhabits a wide variety of cults and secret societies, some of which are particularly dangerous.'
e['A0938-B0066']='翻滚区——戈尔戈尼德周围的外缘地区，也是农奴偶尔能走出矿区前往的唯一地方。各类交易、雇凶杀人和肮脏勾当在此进行。据说，破碎区的变种人也会沿秘密隧道来到这里。\n\n'+head+' 戈尔戈尼德的教派\n\n'+ens+'\n\n戈尔戈尼德存在各式教派与秘密结社，其中一些极其危险。'
t=b938['A0938-B0074'];en=t[t.index('Stable warp routes'):t.index('稳定的亚空间航线')]
e['A0938-B0074']='恶意兄弟会——星球曾爆发一场叛乱：一个不知名的混沌教派，许诺矿工摆脱苦役与帝皇的什一税。审判庭揭露并铲除了该教派，部分亵渎文献的抄本却流传下来。读到它们的矿工深受震动，一些人结社，认定这颗世界不配获得宽恕，只应由帝国摧毁或执行灭绝令。他们自称恶意兄弟会，决意制造足够多的麻烦，引来帝国彻底清洗星球。但瑟菲瑞斯次星对卡利西斯太过重要，当局选择只铲除兄弟会。邪教徒毁坏了一处重要设施后，帝国卫队第 97 营抵达，经过两天激战摧毁其主要力量。少数幸存者逃入破碎区，卫队尾随深入，却不仅遇上邪教残党，还遭遇变种人与恶魔。那里有一块诡异危险的对立之石，能把人变成畸形怪物。下到破碎区的士兵，只有少数回来，语无伦次地念叨鲜血、变种人与死亡。政委尼希利厄斯下令全面封锁该区，向审判庭求援。实际赶来的不是审判官本人，而是其侍从。他们凭借运气、近乎无知的冒险与勇气，终于摧毁石头，完成任务。至于恶意兄弟会这些异端，是否与当地更大的混沌教派有关，依旧无人知晓。\n\n'+en+'\n\n稳定的亚空间航路将瑟菲瑞斯次星连接至辛提拉、伊卡索斯、费德里德与甘夫·马格纳。这里也是慈悲号行经的世界之一。\n\nNotes 注释'
